ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns urn urn:sap-com:document:sap:rfc:functions
---
{
    soapenv#Envelope: {
        soapenv#Header: null,
        soapenv#Body: {
           urn#ZRFC_TRAMITE_RECONEXION: payload.ZRFC_TRAMITE_RECONEXION          
        }
    }         
}

%dw 2.0
output application/json
---
ReconnectionRMCAOutput: {
    WSResponseHeader2: {
        System: {
            name: "MuleSoft",
            correlationID: vars.correlationID,
            processingServer: "MuleSoft"
        },
        Service: {
            status: "PASS",
            responseDate: now() as DateTime as String {format: "yyyy-MM-dd"}
        }
    },
    ZRFC_TRAMITE_RECONEXIONResponse: {
        T_RETURN: payload.Envelope.Body.ZRFC_TRAMITE_RECONEXIONResponse.T_RETURN..*item
    }
}

%dw 2.0
output application/json
ns ns1 http://www.tibco.com/schemas/ETB.NPLAY.SI.SAP.RMCA.Tx/ETB.NPLAY.SAP.RMCA.Core/ReconnectionRMCA/Schema/Schema.xsd
ns ns2 urn:sap-com:document:sap:rfc:functions
---
{
    ns1#ReconnectionRMCAOutput: {
        ns2#WSResponseHeader2: {
            System: {
                name: "Tibco",
                correlationID: "asd",
                processingServer: "Tibco"
            },
            Service: {
                status: "FAIL",
                responseDate: now(),
                statusDetail:{
                    errorCode: payload.ns1#ReconnectionRMCAOutput.ns2#WSResponseHeader2.Service.statusDetail.errorCode,
                    errorMessage: payload.ns1#ReconnectionRMCAOutput.ns2#WSResponseHeader2.Service.statusDetail.errorMessage
                }
            }
        }
    }
}
